"""Typed builders. Generated by `python -m ekbatan.codegen gpkg.model`.

Regenerate this when a model gains or loses a field. A stale builder is a type error
rather than a wrong answer: build() calls the real constructor, which will refuse.
"""

from __future__ import annotations

from decimal import Decimal
from ekbatan.domain import ModelBuilder
from typing import Self, TYPE_CHECKING
from uuid import UUID

if TYPE_CHECKING:
    from ekbatan.domain import GenericState  # noqa: F401
    from ekbatan.ids import Id  # noqa: F401
    from .model import Wallet  # noqa: F401

class WalletBuilder(ModelBuilder["Wallet", "Id[Wallet]", "GenericState"]):
    """Builds a Wallet, with the field types a checker can see.

    id, state, version and the timestamps come from ModelBuilder, typed by the
    parameters above, so only the fields Wallet added are declared here.
    """

    builds_ref = "gpkg.model:Wallet"

    def owner_id(self, value: UUID) -> Self:
        return self.set(owner_id=value)

    def balance(self, value: Decimal) -> Self:
        return self.set(balance=value)

    def memo(self, value: str) -> Self:
        return self.set(memo=value)

def wallet(source: Wallet | None = None) -> WalletBuilder:
    """A fresh WalletBuilder, optionally pre-loaded from an existing Wallet."""
    made = WalletBuilder()
    return made.copy_base(source) if source is not None else made
